/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field DlvMode.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeSalesLineDlvMode extends UPSPricingAttributeSalesLine implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, DlvMode);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    SalesLine   salesLine;

    while select salesLine
        group by DlvMode
    {
        if (! ret.in(salesLine.DlvMode))
        {
            ret.add(salesLine.DlvMode);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesLine, DlvMode));
    qbr.value(queryValue(_value));
}
